-- ############################################################################
-- ## AlterSched_BSIT_Panel_Batch1.sql
-- ############################################################################
-- AlterSched BSIT Panel Revision - Batch 1
-- SAFE MIGRATION: run on the existing AlterSched database. Do not reset/drop old tables.

begin;

-- Subject Catalog metadata used directly by the BSIT scheduler.
alter table public.subjects
  add column if not exists default_year_level integer,
  add column if not exists default_room_type_id uuid references public.room_types(id) on delete set null;

do $$ begin
  alter table public.subjects add constraint subjects_default_year_level_check
    check (default_year_level is null or default_year_level between 1 and 4);
exception when duplicate_object then null; end $$;

-- Keep schedule_entries.entry_type for schedule category (regular/makeup/special).
-- Lecture/Lab and delivery mode are separate concepts.
alter table public.schedule_entries
  add column if not exists session_type text not null default 'lecture',
  add column if not exists delivery_mode text not null default 'onsite';

do $$ begin
  alter table public.schedule_entries add constraint schedule_entries_session_type_check
    check (session_type in ('lecture','lab'));
exception when duplicate_object then null; end $$;

do $$ begin
  alter table public.schedule_entries add constraint schedule_entries_delivery_mode_check
    check (delivery_mode in ('onsite','async','online','hybrid'));
exception when duplicate_object then null; end $$;

-- Import audit. Each uploaded workbook receives one batch record.
create table if not exists public.study_load_imports (
  id uuid primary key default gen_random_uuid(),
  semester_id uuid not null references public.semesters(id) on delete cascade,
  program_id uuid not null references public.programs(id) on delete restrict,
  file_name text not null,
  total_rows integer not null default 0,
  imported_rows integer not null default 0,
  rejected_rows integer not null default 0,
  status text not null default 'completed' check (status in ('completed','completed_with_errors','failed')),
  error_summary jsonb not null default '[]'::jsonb,
  imported_by uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now()
);

create index if not exists study_load_imports_semester_idx on public.study_load_imports(semester_id, created_at desc);
create index if not exists subjects_default_year_idx on public.subjects(default_year_level);
create index if not exists class_offerings_semester_section_subject_idx on public.class_offerings(semester_id, section_id, subject_id);

alter table public.study_load_imports enable row level security;

drop policy if exists study_load_imports_super_admin_all on public.study_load_imports;
create policy study_load_imports_super_admin_all on public.study_load_imports
for all to authenticated
using (
  exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'super_admin' and p.account_status = 'approved')
)
with check (
  exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'super_admin' and p.account_status = 'approved')
);

commit;


-- ############################################################################
-- ## AlterSched_Professional_V2.sql
-- ############################################################################
-- AlterSched Professional V2
-- Run AFTER the existing AlterSched schema and BSIT Panel Batch 1 migration.
-- This migration intentionally preserves legacy student/curriculum tables for safe rollback,
-- but the V2 application no longer exposes them in the active workflow.

create extension if not exists pgcrypto with schema extensions;

-- Instructor registration now creates both the account profile and faculty profile.
create or replace function public.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public, extensions
as $$
declare
  v_role public.user_role;
  v_department uuid;
  v_employee text;
begin
  v_role := case
    when coalesce(new.raw_user_meta_data ->> 'role','') = 'faculty' then 'faculty'::public.user_role
    else 'faculty'::public.user_role
  end;

  insert into public.profiles(id,email,full_name,role,account_status)
  values(new.id,new.email,coalesce(new.raw_user_meta_data ->> 'full_name',''),v_role,'pending')
  on conflict(id) do update set email=excluded.email, full_name=excluded.full_name;

  v_department := nullif(new.raw_user_meta_data ->> 'department_id','')::uuid;
  v_employee := nullif(new.raw_user_meta_data ->> 'employee_id','');

  if v_role = 'faculty' and v_department is not null and v_employee is not null then
    insert into public.faculty_profiles(profile_id,employee_id,department_id,employment_type,max_teaching_load)
    values(new.id,v_employee,v_department,'full_time',18)
    on conflict(profile_id) do nothing;
  end if;
  return new;
end;
$$;

-- Email delivery queue. The application can send immediately through a configured provider
-- and retains a durable record for retry/audit.
create table if not exists public.email_notifications (
  id uuid primary key default gen_random_uuid(),
  profile_id uuid references public.profiles(id) on delete cascade,
  email text not null,
  subject text not null,
  message text not null,
  reference_type text,
  reference_id uuid,
  status text not null default 'pending' check(status in ('pending','sent','failed')),
  attempts integer not null default 0,
  last_error text,
  sent_at timestamptz,
  created_at timestamptz not null default now()
);

-- Public QR shares replace student accounts/claims in the V2 workflow.
create table if not exists public.public_schedule_shares (
  id uuid primary key default gen_random_uuid(),
  schedule_id uuid not null references public.schedules(id) on delete cascade,
  schedule_version_id uuid not null references public.schedule_versions(id) on delete cascade,
  token_hash text not null unique,
  active boolean not null default true,
  expires_at timestamptz,
  generated_by uuid not null references public.profiles(id) on delete restrict,
  created_at timestamptz not null default now(),
  revoked_at timestamptz
);
create index if not exists idx_public_schedule_shares_schedule on public.public_schedule_shares(schedule_id,active);

alter table public.email_notifications enable row level security;
alter table public.public_schedule_shares enable row level security;

drop policy if exists email_notifications_staff_read on public.email_notifications;
create policy email_notifications_staff_read on public.email_notifications for select to authenticated
using (public.current_user_role() in ('super_admin','department_scheduler'));

drop policy if exists public_schedule_shares_staff_all on public.public_schedule_shares;
create policy public_schedule_shares_staff_all on public.public_schedule_shares for all to authenticated
using (public.current_user_role() in ('super_admin','department_scheduler'))
with check (public.current_user_role() in ('super_admin','department_scheduler'));

-- Safe public QR resolver. It exposes only published timetable information.
create or replace function public.get_public_schedule_by_token(p_token text)
returns jsonb
language plpgsql
security definer
set search_path = public, extensions
as $$
declare v_share public.public_schedule_shares%rowtype; v_result jsonb;
begin
  select * into v_share from public.public_schedule_shares
  where token_hash = encode(digest(trim(p_token),'sha256'),'hex')
    and active = true and (expires_at is null or expires_at > now())
  limit 1;
  if v_share.id is null then return null; end if;
  if not exists(select 1 from public.schedules s where s.id=v_share.schedule_id and s.status='published' and s.current_version_id=v_share.schedule_version_id) then return null; end if;

  select jsonb_build_object(
    'schedule_id',s.id,'title',s.title,'status',s.status,
    'semester',sem.name,'academic_year',ay.name,'block',sec.code,'program',prog.code,
    'entries',coalesce((select jsonb_agg(jsonb_build_object(
      'day_of_week',e.day_of_week,'start_time',e.start_time,'end_time',e.end_time,
      'room',r.code,'subject_code',sub.code,'subject',sub.name,
      'instructor',p.full_name,'session_type',coalesce(e.session_type,'lecture')
    ) order by e.day_of_week,e.start_time)
    from public.schedule_entries e
    join public.class_offerings co on co.id=e.class_offering_id
    join public.subjects sub on sub.id=co.subject_id
    left join public.rooms r on r.id=e.room_id
    left join public.faculty_profiles fp on fp.id=e.faculty_id
    left join public.profiles p on p.id=fp.profile_id
    where e.schedule_version_id=v_share.schedule_version_id),'[]'::jsonb)
  ) into v_result
  from public.schedules s
  left join public.semesters sem on sem.id=s.semester_id
  left join public.academic_years ay on ay.id=sem.academic_year_id
  left join public.sections sec on sec.id=s.section_id
  left join public.programs prog on prog.id=s.program_id
  where s.id=v_share.schedule_id;
  return v_result;
end;
$$;
grant execute on function public.get_public_schedule_by_token(text) to anon, authenticated;


-- ############################################################################
-- ## AlterSched_Claim_Workflow.sql
-- ############################################################################
-- Secure raw-code claim wrapper. Run after AlterSched_Database_V2.sql.
begin;
create or replace function public.claim_schedule_with_code(p_raw_code text,p_claim_method public.claim_method default 'code') returns uuid
language plpgsql security definer set search_path=public as $$
declare v_id uuid; v_hash text;
begin
 if auth.uid() is null then raise exception 'Authentication required'; end if;
 if coalesce(trim(p_raw_code),'')='' then raise exception 'Schedule access code is required'; end if;
 v_hash:=encode(digest(upper(trim(p_raw_code)),'sha256'),'hex');
 if p_claim_method='qr' then select id into v_id from public.schedule_access_codes where qr_token_hash=v_hash and active=true and revoked_at is null limit 1;
 else select id into v_id from public.schedule_access_codes where code_hash=v_hash and active=true and revoked_at is null limit 1; end if;
 if v_id is null then raise exception 'Invalid or inactive schedule access code'; end if;
 return public.claim_schedule(v_id,p_claim_method);
end;$$;
grant execute on function public.claim_schedule_with_code(text,public.claim_method) to authenticated;
commit;


-- ############################################################################
-- ## AlterSched_Change_Request_Policies.sql
-- ############################################################################
-- Faculty alteration request write policy + manager review policy.
begin;
drop policy if exists schedule_change_requests_faculty_insert on public.schedule_change_requests;
create policy schedule_change_requests_faculty_insert on public.schedule_change_requests for insert to authenticated with check (
 requested_by=auth.uid() and exists(select 1 from public.profiles p where p.id=auth.uid() and p.role in ('faculty','department_scheduler') and p.account_status='approved')
);
drop policy if exists schedule_change_requests_manager_update on public.schedule_change_requests;
create policy schedule_change_requests_manager_update on public.schedule_change_requests for update to authenticated using (
 public.is_super_admin() or exists(select 1 from public.schedule_entries se join public.schedule_versions sv on sv.id=se.schedule_version_id join public.schedules sc on sc.id=sv.schedule_id where se.id=schedule_entry_id and public.can_manage_department(sc.department_id))
) with check (public.is_super_admin() or exists(select 1 from public.schedule_entries se join public.schedule_versions sv on sv.id=se.schedule_version_id join public.schedules sc on sc.id=sv.schedule_id where se.id=schedule_entry_id and public.can_manage_department(sc.department_id)));
commit;


-- ############################################################################
-- ## AlterSched_Admin_Write_Policies.sql
-- ############################################################################
-- AlterSched admin write-policy patch
-- Run once in Supabase SQL Editor after AlterSched_Database_V2.sql.
-- Keeps reads scoped by existing policies while allowing approved Super Admin writes.

begin;

do $$
declare t text;
begin
  foreach t in array array[
    'academic_years','semesters','departments','programs','year_levels','sections','room_types',
    'subjects','curricula','curriculum_subjects','faculty_profiles','faculty_subjects','faculty_availability',
    'rooms','room_availability','class_offerings','schedules','schedule_versions','schedule_entries',
    'schedule_validation_logs','schedule_access_codes','schedule_change_requests','schedule_revision_history',
    'notifications','notification_acknowledgements'
  ] loop
    execute format('drop policy if exists %I_super_admin_insert on public.%I', t, t);
    execute format('create policy %I_super_admin_insert on public.%I for insert to authenticated with check (public.is_super_admin())', t, t);
    execute format('drop policy if exists %I_super_admin_update on public.%I', t, t);
    execute format('create policy %I_super_admin_update on public.%I for update to authenticated using (public.is_super_admin()) with check (public.is_super_admin())', t, t);
    execute format('drop policy if exists %I_super_admin_delete on public.%I', t, t);
    execute format('create policy %I_super_admin_delete on public.%I for delete to authenticated using (public.is_super_admin())', t, t);
  end loop;
end $$;

commit;


-- ############################################################################
-- ## AlterSched_Final_RLS.sql
-- ############################################################################
-- Final non-recursive schedule read policies.
-- Run after the base schema and prior policy patches.
begin;
create or replace function public.can_read_schedule(p_schedule_id uuid)
returns boolean language sql stable security definer set search_path=public as $$
 select public.is_super_admin()
 or exists(select 1 from public.schedules s where s.id=p_schedule_id and public.can_manage_department(s.department_id))
 or exists(select 1 from public.schedule_memberships sm join public.student_profiles sp on sp.id=sm.student_profile_id where sm.schedule_id=p_schedule_id and sm.active=true and sp.profile_id=auth.uid())
 or exists(select 1 from public.schedule_versions sv join public.schedule_entries se on se.schedule_version_id=sv.id join public.faculty_profiles fp on fp.id=se.faculty_id where sv.schedule_id=p_schedule_id and fp.profile_id=auth.uid());
$$;
grant execute on function public.can_read_schedule(uuid) to authenticated;
drop policy if exists schedules_select on public.schedules;
create policy schedules_select on public.schedules for select to authenticated using(public.can_read_schedule(id));
drop policy if exists schedule_versions_select on public.schedule_versions;
create policy schedule_versions_select on public.schedule_versions for select to authenticated using(public.can_read_schedule(schedule_id));
drop policy if exists schedule_entries_select on public.schedule_entries;
create policy schedule_entries_select on public.schedule_entries for select to authenticated using(exists(select 1 from public.schedule_versions sv where sv.id=schedule_version_id and public.can_read_schedule(sv.schedule_id)));
commit;


-- ############################################################################
-- ## AlterSched_V6_Fixes.sql
-- ############################################################################
-- AlterSched V6 fixes
-- Run AFTER all earlier migrations (see SETUP.md for the full order).
-- Safe to run more than once. Does not delete any data.

begin;

-- 1. Subject Catalog "default instructor" (used by /admin/subjects).
--    The page and the save action read/write this column, but no migration created it,
--    so the whole Subject Catalog query failed and the page showed no subjects.
alter table public.subjects
  add column if not exists default_faculty_id uuid
  references public.faculty_profiles(id) on delete set null;

create index if not exists subjects_default_faculty_id_idx
  on public.subjects(default_faculty_id);

-- =====================================================================
-- 2. ROW LEVEL SECURITY: make the policies match what each portal does.
--    Before this, many app actions silently did nothing because no
--    policy allowed them (Supabase returns 0 rows instead of an error):
--      * Admin could not approve/reject/suspend accounts or promote a
--        Scheduler (profiles had no UPDATE policy).
--      * Department Schedulers could not create schedules, versions,
--        entries, class offerings, notifications or revision history.
--      * Nobody could read instructor qualifications (faculty_subjects),
--        room availability, validation/conflict logs or revision history.
--      * Schedulers could not read instructor names (profiles) or their
--        own department assignment (scheduler_departments).
-- =====================================================================

-- Helper: can the current user manage (edit) this schedule?
create or replace function public.can_manage_schedule(p_schedule_id uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select public.is_super_admin()
      or exists (select 1 from public.schedules s
                 where s.id = p_schedule_id and public.can_manage_department(s.department_id));
$$;

create or replace function public.can_manage_schedule_version(p_version_id uuid)
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.schedule_versions v
                 where v.id = p_version_id and public.can_manage_schedule(v.schedule_id));
$$;

-- Helper: is the current user an approved department scheduler (any department)?
create or replace function public.is_department_scheduler()
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.profiles
                 where id = auth.uid() and role = 'department_scheduler' and account_status = 'approved');
$$;

grant execute on function public.can_manage_schedule(uuid) to authenticated;
grant execute on function public.can_manage_schedule_version(uuid) to authenticated;
grant execute on function public.is_department_scheduler() to authenticated;

-- profiles ------------------------------------------------------------
drop policy if exists profiles_super_admin_update on public.profiles;
create policy profiles_super_admin_update on public.profiles
  for update to authenticated using (public.is_super_admin()) with check (public.is_super_admin());

-- Schedulers may read the account records of instructors in departments they manage.
drop policy if exists profiles_scheduler_read_department_faculty on public.profiles;
create policy profiles_scheduler_read_department_faculty on public.profiles
  for select to authenticated using (
    exists (select 1 from public.faculty_profiles fp
            where fp.profile_id = profiles.id and public.can_manage_department(fp.department_id))
  );

-- account_approvals -----------------------------------------------------
drop policy if exists account_approvals_select on public.account_approvals;
create policy account_approvals_select on public.account_approvals
  for select to authenticated using (profile_id = auth.uid() or public.is_super_admin());
drop policy if exists account_approvals_super_admin_write on public.account_approvals;
create policy account_approvals_super_admin_write on public.account_approvals
  for all to authenticated using (public.is_super_admin()) with check (public.is_super_admin());

-- audit_logs ------------------------------------------------------------
drop policy if exists audit_logs_super_admin_read on public.audit_logs;
create policy audit_logs_super_admin_read on public.audit_logs
  for select to authenticated using (public.is_super_admin());
drop policy if exists audit_logs_actor_insert on public.audit_logs;
create policy audit_logs_actor_insert on public.audit_logs
  for insert to authenticated with check (actor_profile_id = auth.uid() and public.is_approved_user());

-- scheduler_departments -------------------------------------------------
drop policy if exists scheduler_departments_select on public.scheduler_departments;
create policy scheduler_departments_select on public.scheduler_departments
  for select to authenticated using (profile_id = auth.uid() or public.is_super_admin());
drop policy if exists scheduler_departments_super_admin_write on public.scheduler_departments;
create policy scheduler_departments_super_admin_write on public.scheduler_departments
  for all to authenticated using (public.is_super_admin()) with check (public.is_super_admin());

-- faculty_subjects (instructor qualifications) --------------------------
drop policy if exists faculty_subjects_select on public.faculty_subjects;
create policy faculty_subjects_select on public.faculty_subjects
  for select to authenticated using (
    public.is_super_admin()
    or exists (select 1 from public.faculty_profiles fp
               where fp.id = faculty_subjects.faculty_id
                 and (fp.profile_id = auth.uid() or public.can_manage_department(fp.department_id)))
  );

-- room_availability -------------------------------------------------------
drop policy if exists room_availability_read_approved on public.room_availability;
create policy room_availability_read_approved on public.room_availability
  for select to authenticated using (public.is_approved_user());

-- class_offerings: schedulers prepare offerings for their department ------
drop policy if exists class_offerings_scheduler_insert on public.class_offerings;
create policy class_offerings_scheduler_insert on public.class_offerings
  for insert to authenticated with check (
    exists (select 1 from public.subjects sub where sub.id = class_offerings.subject_id and public.can_manage_department(sub.department_id))
  );
drop policy if exists class_offerings_scheduler_update on public.class_offerings;
create policy class_offerings_scheduler_update on public.class_offerings
  for update to authenticated
  using (exists (select 1 from public.subjects sub where sub.id = class_offerings.subject_id and public.can_manage_department(sub.department_id)))
  with check (exists (select 1 from public.subjects sub where sub.id = class_offerings.subject_id and public.can_manage_department(sub.department_id)));

-- schedules / versions / entries: scheduler owns drafts in their department --
drop policy if exists schedules_scheduler_insert on public.schedules;
create policy schedules_scheduler_insert on public.schedules
  for insert to authenticated with check (public.can_manage_department(department_id));
drop policy if exists schedules_scheduler_update on public.schedules;
create policy schedules_scheduler_update on public.schedules
  for update to authenticated using (public.can_manage_department(department_id)) with check (public.can_manage_department(department_id));

-- The existing schedules SELECT policy calls can_read_schedule(id), which looks the
-- row up again by id. A row inserted by the same statement is not visible to that
-- lookup, so `insert ... returning` (supabase .insert().select()) failed with
-- "new row violates row-level security policy" for schedulers. This policy checks
-- the row's own department_id instead.
drop policy if exists schedules_manager_select on public.schedules;
create policy schedules_manager_select on public.schedules
  for select to authenticated using (public.can_manage_department(department_id));

drop policy if exists schedule_versions_scheduler_insert on public.schedule_versions;
create policy schedule_versions_scheduler_insert on public.schedule_versions
  for insert to authenticated with check (public.can_manage_schedule(schedule_id));
drop policy if exists schedule_versions_scheduler_update on public.schedule_versions;
create policy schedule_versions_scheduler_update on public.schedule_versions
  for update to authenticated using (public.can_manage_schedule(schedule_id)) with check (public.can_manage_schedule(schedule_id));
drop policy if exists schedule_versions_scheduler_delete on public.schedule_versions;
create policy schedule_versions_scheduler_delete on public.schedule_versions
  for delete to authenticated using (public.can_manage_schedule(schedule_id) and status = 'draft');

drop policy if exists schedule_entries_scheduler_insert on public.schedule_entries;
create policy schedule_entries_scheduler_insert on public.schedule_entries
  for insert to authenticated with check (public.can_manage_schedule_version(schedule_version_id));
drop policy if exists schedule_entries_scheduler_update on public.schedule_entries;
create policy schedule_entries_scheduler_update on public.schedule_entries
  for update to authenticated using (public.can_manage_schedule_version(schedule_version_id)) with check (public.can_manage_schedule_version(schedule_version_id));
drop policy if exists schedule_entries_scheduler_delete on public.schedule_entries;
create policy schedule_entries_scheduler_delete on public.schedule_entries
  for delete to authenticated using (public.can_manage_schedule_version(schedule_version_id));

-- validation logs (conflict results) ---------------------------------------
drop policy if exists schedule_validation_logs_select on public.schedule_validation_logs;
create policy schedule_validation_logs_select on public.schedule_validation_logs
  for select to authenticated using (
    exists (select 1 from public.schedule_versions v where v.id = schedule_validation_logs.schedule_version_id and public.can_read_schedule(v.schedule_id))
  );
drop policy if exists schedule_validation_logs_scheduler_write on public.schedule_validation_logs;
create policy schedule_validation_logs_scheduler_write on public.schedule_validation_logs
  for all to authenticated
  using (public.can_manage_schedule_version(schedule_version_id))
  with check (public.can_manage_schedule_version(schedule_version_id));

-- revision history -----------------------------------------------------------
drop policy if exists schedule_revision_history_select on public.schedule_revision_history;
create policy schedule_revision_history_select on public.schedule_revision_history
  for select to authenticated using (public.can_read_schedule(schedule_id));
drop policy if exists schedule_revision_history_scheduler_insert on public.schedule_revision_history;
create policy schedule_revision_history_scheduler_insert on public.schedule_revision_history
  for insert to authenticated with check (public.can_manage_schedule(schedule_id) and changed_by = auth.uid());

-- change requests: instructors may cancel/edit their own pending requests ------
drop policy if exists schedule_change_requests_owner_update on public.schedule_change_requests;
create policy schedule_change_requests_owner_update on public.schedule_change_requests
  for update to authenticated
  using (requested_by = auth.uid() and status = 'pending')
  with check (requested_by = auth.uid());

-- notifications: staff notify instructors; users mark their own as read --------
drop policy if exists notifications_scheduler_insert on public.notifications;
create policy notifications_scheduler_insert on public.notifications
  for insert to authenticated with check (public.is_department_scheduler());
drop policy if exists notifications_owner_update on public.notifications;
create policy notifications_owner_update on public.notifications
  for update to authenticated using (profile_id = auth.uid()) with check (profile_id = auth.uid());

-- email audit rows written when publishing --------------------------------------
drop policy if exists email_notifications_staff_insert on public.email_notifications;
create policy email_notifications_staff_insert on public.email_notifications
  for insert to authenticated with check (public.is_super_admin() or public.is_department_scheduler());
drop policy if exists email_notifications_staff_update on public.email_notifications;
create policy email_notifications_staff_update on public.email_notifications
  for update to authenticated using (public.is_super_admin() or public.is_department_scheduler())
  with check (public.is_super_admin() or public.is_department_scheduler());

-- schedule_access_codes (admin only) ---------------------------------------------
drop policy if exists schedule_access_codes_super_admin_read on public.schedule_access_codes;
create policy schedule_access_codes_super_admin_read on public.schedule_access_codes
  for select to authenticated using (public.is_super_admin());

-- 3. Existing schedulers promoted before this fix have no department
--    assignment, so can_manage_department() is false for them. Give each one
--    their own faculty department (the promote action now does this too).
insert into public.scheduler_departments (profile_id, department_id, active)
select p.id, fp.department_id, true
from public.profiles p
join public.faculty_profiles fp on fp.profile_id = p.id
where p.role = 'department_scheduler'
  and not exists (select 1 from public.scheduler_departments sd
                  where sd.profile_id = p.id and sd.department_id = fp.department_id);

-- =====================================================================
-- 4. OFFICIAL PUBLISHED VERSION
--    schedules.current_version_id is the *working* version. When a
--    Scheduler approves an alteration, a new draft version becomes current,
--    and every read-only view that relied on current_version_id lost the
--    published timetable until the Admin re-published (instructors saw
--    their classes disappear; the public QR link returned "not found").
--    published_version_id always points to the latest published version.
-- =====================================================================
alter table public.schedules
  add column if not exists published_version_id uuid
  references public.schedule_versions(id) on delete set null;

-- Backfill: latest published version of each schedule.
update public.schedules s
set published_version_id = v.id
from (
  select distinct on (schedule_id) id, schedule_id
  from public.schedule_versions
  where status = 'published'
  order by schedule_id, version_number desc
) v
where v.schedule_id = s.id
  and s.published_version_id is distinct from v.id;

-- Keep it in sync, and archive the previously published version so only one
-- version per schedule is ever "published".
create or replace function public.sync_published_version()
returns trigger language plpgsql security definer set search_path = public as $$
begin
  if new.status = 'published' and (tg_op = 'INSERT' or old.status is distinct from 'published') then
    update public.schedule_versions
       set status = 'archived'
     where schedule_id = new.schedule_id
       and id <> new.id
       and status = 'published';
    update public.schedules
       set published_version_id = new.id
     where id = new.schedule_id;
  elsif tg_op = 'UPDATE' and old.status = 'published' and new.status <> 'published' then
    -- Publication undone (e.g. publish rollback): fall back to the latest other published version.
    update public.schedules s
       set published_version_id = (
         select v.id from public.schedule_versions v
          where v.schedule_id = new.schedule_id and v.status = 'published' and v.id <> new.id
          order by v.version_number desc limit 1)
     where s.id = new.schedule_id and s.published_version_id = new.id;
  end if;
  return new;
end;
$$;

drop trigger if exists schedule_versions_sync_published on public.schedule_versions;
create trigger schedule_versions_sync_published
  after insert or update of status on public.schedule_versions
  for each row execute function public.sync_published_version();

-- Public link: always show the schedule's current official version, so a QR code
-- handed out to students keeps working after an approved alteration is re-published.
create or replace function public.get_public_schedule_by_token(p_token text)
returns jsonb language plpgsql stable security definer set search_path = public, extensions as $$
declare v_share public.public_schedule_shares%rowtype; v_version uuid; v_result jsonb;
begin
  select * into v_share from public.public_schedule_shares
  where token_hash = encode(digest(trim(p_token), 'sha256'), 'hex')
    and active = true and (expires_at is null or expires_at > now())
  limit 1;
  if v_share.id is null then return null; end if;

  select s.published_version_id into v_version
  from public.schedules s
  where s.id = v_share.schedule_id and s.status <> 'archived';
  if v_version is null then return null; end if;

  select jsonb_build_object(
    'schedule_id', s.id, 'title', s.title, 'status', 'published',
    'semester', sem.name, 'academic_year', ay.name, 'block', sec.code, 'program', prog.code,
    'entries', coalesce((select jsonb_agg(jsonb_build_object(
      'day_of_week', e.day_of_week, 'start_time', e.start_time, 'end_time', e.end_time,
      'room', r.code, 'subject_code', sub.code, 'subject', sub.name,
      'instructor', p.full_name, 'session_type', coalesce(e.session_type, 'lecture')
    ) order by e.day_of_week, e.start_time)
    from public.schedule_entries e
    join public.class_offerings co on co.id = e.class_offering_id
    join public.subjects sub on sub.id = co.subject_id
    left join public.rooms r on r.id = e.room_id
    left join public.faculty_profiles fp on fp.id = e.faculty_id
    left join public.profiles p on p.id = fp.profile_id
    where e.schedule_version_id = v_version), '[]'::jsonb)
  ) into v_result
  from public.schedules s
  left join public.semesters sem on sem.id = s.semester_id
  left join public.academic_years ay on ay.id = sem.academic_year_id
  left join public.sections sec on sec.id = s.section_id
  left join public.programs prog on prog.id = s.program_id
  where s.id = v_share.schedule_id;
  return v_result;
end;
$$;
grant execute on function public.get_public_schedule_by_token(text) to anon, authenticated;

commit;


-- ############################################################################
-- ## AlterSched_V7_Assignments.sql
-- ############################################################################
-- AlterSched V7 — instructor assignment editing
-- Run AFTER AlterSched_V6_Fixes.sql. Safe to run more than once. Does not delete data.
--
-- Background: the instructor of a class is stored on class_offerings.faculty_id, and the
-- validate_schedule_entry_alignment trigger requires every schedule entry (session) to use
-- that same instructor. Editors that changed only the session were therefore rejected, and
-- changing it on the offering left existing draft sessions out of sync.
--
-- This migration adds one way to change an instructor that keeps everything aligned, and
-- makes draft saves all-or-nothing.

begin;

-- 1. Remember whether the current instructor was chosen by the generator or by a person.
alter table public.class_offerings
  add column if not exists assignment_mode text;

do $$ begin
  alter table public.class_offerings
    add constraint class_offerings_assignment_mode_check
    check (assignment_mode is null or assignment_mode in ('auto', 'manual'));
exception when duplicate_object then null; end $$;

-- Existing assignments were made before this column existed; treat them as automatic.
update public.class_offerings
set assignment_mode = 'auto'
where faculty_id is not null and assignment_mode is null;

-- 2. Change the instructor of a class offering (lecture + lab) in one transaction.
--    Updates the offering and every session of it in the schedule's *current draft*.
--    Published/submitted versions are history and are left untouched.
--    SECURITY INVOKER: row level security still decides who may do this.
create or replace function public.assign_offering_instructor(
  p_offering_id uuid,
  p_faculty_id uuid,
  p_mode text default 'manual'
)
returns integer
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_subject uuid;
  v_updated integer;
begin
  if p_mode not in ('auto', 'manual') then
    raise exception 'Invalid assignment mode %', p_mode;
  end if;

  select subject_id into v_subject from public.class_offerings where id = p_offering_id;
  if v_subject is null then
    raise exception 'Class offering not found or you are not allowed to change it.';
  end if;

  if p_faculty_id is not null and not exists (
    select 1 from public.faculty_subjects fs
    where fs.faculty_id = p_faculty_id and fs.subject_id = v_subject
  ) then
    raise exception 'This instructor is not qualified to teach the subject.';
  end if;

  update public.class_offerings
  set faculty_id = p_faculty_id,
      assignment_mode = case when p_faculty_id is null then null else p_mode end,
      updated_at = now()
  where id = p_offering_id;

  if not found then
    raise exception 'Class offering not found or you are not allowed to change it.';
  end if;

  update public.schedule_entries e
  set faculty_id = p_faculty_id
  from public.schedule_versions v
  join public.schedules s on s.current_version_id = v.id
  where e.schedule_version_id = v.id
    and v.status = 'draft'
    and e.class_offering_id = p_offering_id
    and e.faculty_id is distinct from p_faculty_id;

  get diagnostics v_updated = row_count;
  return v_updated;
end;
$$;

grant execute on function public.assign_offering_instructor(uuid, uuid, text) to authenticated;

-- 3. New sessions always follow their class offering's instructor. This keeps copies of
--    older versions (alteration approvals) consistent after an instructor was changed.
--    Updates are still checked strictly: change instructors with assign_offering_instructor.
create or replace function public.validate_schedule_entry_alignment()
returns trigger
language plpgsql
as $$
declare
  v_offering_section uuid;
  v_offering_faculty uuid;
  v_expected integer;
  v_capacity integer;
begin
  select section_id, faculty_id, expected_students
  into v_offering_section, v_offering_faculty, v_expected
  from public.class_offerings
  where id = new.class_offering_id;

  if v_offering_section is distinct from new.section_id then
    raise exception 'Schedule entry section does not match class offering section';
  end if;

  if v_offering_faculty is not null and new.faculty_id is distinct from v_offering_faculty then
    if tg_op = 'INSERT' then
      new.faculty_id := v_offering_faculty;
    else
      raise exception 'Schedule entry faculty does not match class offering faculty';
    end if;
  end if;

  select capacity into v_capacity from public.rooms where id = new.room_id;
  if v_expected is not null and v_capacity is not null and v_capacity < v_expected then
    raise exception 'Room capacity is smaller than expected class size';
  end if;

  return new;
end;
$$;

-- 4. Check overlaps at the end of the transaction instead of row by row, so a save that
--    swaps two classes' time slots is judged on the final timetable.
drop trigger if exists trg_prevent_schedule_entry_overlap on public.schedule_entries;
create constraint trigger trg_prevent_schedule_entry_overlap
  after insert or update on public.schedule_entries
  deferrable initially deferred
  for each row execute function public.prevent_schedule_entry_overlap();

-- 5. Save every edited row of a draft in one transaction (all-or-nothing).
--    p_entries: [{ "id", "faculty_id", "room_id", "day_of_week", "start_time", "end_time" }]
create or replace function public.save_schedule_draft(p_entries jsonb)
returns integer
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_row record;
  v_saved integer := 0;
begin
  if jsonb_typeof(p_entries) <> 'array' or jsonb_array_length(p_entries) = 0 then
    raise exception 'No schedule changes were provided.';
  end if;

  -- Every session of a class must keep the same instructor.
  if exists (
    select 1
    from jsonb_array_elements(p_entries) x
    join public.schedule_entries e on e.id = (x->>'id')::uuid
    group by e.class_offering_id
    having count(distinct coalesce(x->>'faculty_id', '')) > 1
  ) then
    raise exception 'All sessions of a class (lecture and lab) must have the same instructor.';
  end if;

  -- Instructor changes first (once per class), so the sessions below stay aligned.
  for v_row in
    select distinct e.class_offering_id as offering_id, nullif(x->>'faculty_id', '')::uuid as faculty_id
    from jsonb_array_elements(p_entries) x
    join public.schedule_entries e on e.id = (x->>'id')::uuid
    join public.class_offerings o on o.id = e.class_offering_id
    where o.faculty_id is distinct from nullif(x->>'faculty_id', '')::uuid
  loop
    perform public.assign_offering_instructor(v_row.offering_id, v_row.faculty_id, 'manual');
  end loop;

  for v_row in
    select (x->>'id')::uuid as id,
           (x->>'room_id')::uuid as room_id,
           (x->>'day_of_week')::smallint as day_of_week,
           (x->>'start_time')::time as start_time,
           (x->>'end_time')::time as end_time
    from jsonb_array_elements(p_entries) x
  loop
    update public.schedule_entries
    set room_id = v_row.room_id,
        day_of_week = v_row.day_of_week,
        start_time = v_row.start_time,
        end_time = v_row.end_time
    where id = v_row.id;

    if not found then
      raise exception 'Schedule entry % was not found or cannot be edited.', v_row.id;
    end if;
    v_saved := v_saved + 1;
  end loop;

  return v_saved;
end;
$$;

grant execute on function public.save_schedule_draft(jsonb) to authenticated;

commit;


-- ############################################################################
-- ## AlterSched_V8_Scheduling_Settings.sql
-- ############################################################################
-- ============================================================================
-- AlterSched V8 - Schedule generator settings
-- Safe to run more than once. Does not delete data.
--
-- One row of settings the Super Admin can change in Settings:
--   * which days classes may be scheduled (1 = Monday ... 7 = Sunday)
--   * the earliest start and latest end time of a class day
--   * the start-time step the generator tries (15, 30 or 60 minutes)
-- Defaults match the previous fixed values (Monday-Saturday, 07:00-21:00, 30 minutes).
-- ============================================================================

begin;

create table if not exists public.scheduling_settings (
  id boolean primary key default true,
  teaching_days smallint[] not null default '{1,2,3,4,5,6}',
  day_start time not null default '07:00',
  day_end time not null default '21:00',
  slot_minutes smallint not null default 30,
  updated_at timestamptz not null default now(),
  updated_by uuid references public.profiles (id) on delete set null,
  constraint scheduling_settings_single_row check (id),
  constraint scheduling_settings_hours check (day_end > day_start),
  constraint scheduling_settings_slot check (slot_minutes in (15, 30, 60)),
  constraint scheduling_settings_days check (
    cardinality(teaching_days) > 0
    and teaching_days <@ array[1, 2, 3, 4, 5, 6, 7]::smallint[]
  )
);

insert into public.scheduling_settings (id) values (true) on conflict (id) do nothing;

alter table public.scheduling_settings enable row level security;

drop policy if exists scheduling_settings_read on public.scheduling_settings;
create policy scheduling_settings_read on public.scheduling_settings
for select to authenticated
using (true);

drop policy if exists scheduling_settings_super_admin_update on public.scheduling_settings;
create policy scheduling_settings_super_admin_update on public.scheduling_settings
for update to authenticated
using (public.is_super_admin())
with check (public.is_super_admin());

grant select, update on public.scheduling_settings to authenticated;

commit;


-- ############################################################################
-- ## AlterSched_V9_Instructor_Self_Service.sql
-- ############################################################################
-- ============================================================================
-- AlterSched V9 - Instructor self-service
--   1. Instructors can read the classes on their published timetable.
--   2. Instructors can add, change and remove their own availability.
--
-- (1)
-- After a schedule is published, an Admin or Scheduler may hand a class to a
-- different instructor. The published timetable keeps the original instructor
-- until it is republished, but that instructor could no longer read the class
-- record, so their "My Schedule" showed "Class" instead of the subject.
-- Now an instructor can also read any class that appears in one of their own
-- schedule entries. Safe to run more than once.
-- ============================================================================

drop policy if exists class_offerings_select on public.class_offerings;

create policy class_offerings_select on public.class_offerings
  for select to authenticated
  using (
    public.is_super_admin()
    or exists (
      select 1
      from public.faculty_profiles fp
      where fp.id = class_offerings.faculty_id
        and fp.profile_id = auth.uid()
        and public.is_approved_user()
    )
    or exists (
      select 1
      from public.schedule_entries e
      join public.faculty_profiles fp on fp.id = e.faculty_id
      where e.class_offering_id = class_offerings.id
        and fp.profile_id = auth.uid()
        and public.is_approved_user()
    )
    or exists (
      select 1
      from public.subjects sub
      where sub.id = class_offerings.subject_id
        and public.can_manage_department(sub.department_id)
    )
  );

-- (2) Instructors manage their own availability (the Administrator still can too).
drop policy if exists faculty_availability_owner_insert on public.faculty_availability;
drop policy if exists faculty_availability_owner_update on public.faculty_availability;
drop policy if exists faculty_availability_owner_delete on public.faculty_availability;

create policy faculty_availability_owner_insert on public.faculty_availability
  for insert to authenticated
  with check (
    public.is_approved_user()
    and exists (
      select 1 from public.faculty_profiles fp
      where fp.id = faculty_availability.faculty_id and fp.profile_id = auth.uid()
    )
  );

create policy faculty_availability_owner_update on public.faculty_availability
  for update to authenticated
  using (
    public.is_approved_user()
    and exists (
      select 1 from public.faculty_profiles fp
      where fp.id = faculty_availability.faculty_id and fp.profile_id = auth.uid()
    )
  )
  with check (
    exists (
      select 1 from public.faculty_profiles fp
      where fp.id = faculty_availability.faculty_id and fp.profile_id = auth.uid()
    )
  );

create policy faculty_availability_owner_delete on public.faculty_availability
  for delete to authenticated
  using (
    public.is_approved_user()
    and exists (
      select 1 from public.faculty_profiles fp
      where fp.id = faculty_availability.faculty_id and fp.profile_id = auth.uid()
    )
  );

grant insert, update, delete on public.faculty_availability to authenticated;
